import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('fresh system is idle', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle' });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('x'), null);
  assert.equal((await h.workDone('worker0')).ok, false);
  assert.equal((await h.cancel()).ok, false);
});

test('both complete', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  assert.equal((await h.inFlight()).length, 2);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'completed', task1: 'assigned' });
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed' });
});

test('failure waits for both', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.deliverAll();
  assert.equal((await h.run()).status, 'running');
  await h.workDone('worker1');
  await h.deliverAll();
  assert.equal((await h.run()).status, 'failed');
});

test('cancel races with completion', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0'); // report in flight
  assert.deepEqual(await h.cancel(), { ok: true });
  const msgs = await h.inFlight();
  assert.equal(msgs.filter((m) => m.action === 'Abort').length, 2);
  // deliver Aborts first
  for (const m of msgs.filter((m) => m.action === 'Abort')) await h.deliver(m.id);
  assert.equal((await h.run()).status, 'cancelling');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'completed', task1: 'cancelled' });
  assert.equal((await h.cancel()).ok, false);
});

test('cancel before assign delivered', async () => {
  const h = await createHost();
  await h.start();
  await h.cancel();
  const msgs = await h.inFlight();
  for (const m of msgs.filter((m) => m.action === 'Abort')) await h.deliver(m.id);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.equal((await h.run()).status, 'cancelling');
  await h.workDone('worker0');
  await h.workDone('worker1');
  await h.deliverAll();
  assert.equal((await h.run()).status, 'completed');
});

