import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const noRetry = { retried0: false, retried1: false };

test('fresh system is idle', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle', ...noRetry });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('x'), null);
  assert.equal((await h.workDone('worker0')).ok, false);
  assert.equal((await h.cancel()).ok, false);
});

test('both complete', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  assert.equal((await h.inFlight()).length, 2);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'completed', task1: 'assigned', ...noRetry });
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', ...noRetry });
});

test('first failure is retried, second is recorded', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: true, retried1: false });
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workFailed('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal((await h.run()).task0, 'failed');
  assert.equal((await h.run()).status, 'running');
  await h.workDone('worker1');
  await h.deliverAll();
  assert.equal((await h.run()).status, 'failed');
});

test('retry can succeed', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  await h.deliverAll();
  await h.workDone('worker1');
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: true });
});

test('failure while cancelling is not retried', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.cancel();
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'cancelled', ...noRetry });
