import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const noRetry = { retried0: false, retried1: false };

test('fresh system is idle', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle', ...noRetry, processed: 0 });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('x'), null);
  assert.equal((await h.workDone('worker0', 1)).ok, false);
  assert.equal((await h.cancel()).ok, false);
});

test('both complete, items summed', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  assert.equal((await h.inFlight()).length, 2);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.equal((await h.workDone('worker0', 0)).ok, false);
  assert.equal((await h.workDone('worker0', 3)).ok, false);
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workDone('worker0', 2);
  const [rep] = await h.inFlight();
  assert.deepEqual(rep.data, { task: 0, outcome: 'completed', items: 2 });
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'completed', task1: 'assigned', ...noRetry, processed: 2 });
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', ...noRetry, processed: 3 });
});

test('first failure is retried, second is recorded', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  assert.deepEqual((await h.inFlight())[0].data, { task: 0, outcome: 'failed', items: 0 });
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: true, retried1: false, processed: 0 });
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workFailed('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal((await h.run()).task0, 'failed');
  assert.equal((await h.run()).status, 'running');
  await h.workDone('worker1', 2);
  await h.deliverAll();
  assert.equal((await h.run()).status, 'failed');
  assert.equal((await h.run()).processed, 2);
});

test('retry can succeed', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  await h.deliverAll();
  await h.workDone('worker1', 1);
  await h.workDone('worker0', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: true, processed: 2 });
});

test('failure while cancelling is not retried', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.cancel();
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'cancelled', ...noRetry, processed: 0 });
});

test('timeout fails the task without retry and aborts the worker', async () => {
  const h = await createHost();
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.start();
  await h.deliverAll();
  assert.equal((await h.taskTimeout(2)).ok, false);
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  assert.equal((await h.taskTimeout(0)).ok, false);
  assert.deepEqual(await h.run(), { status: 'running', task0: 'failed', task1: 'assigned', ...noRetry, processed: 0 });
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.to, m.action]), [['worker0', 'Abort']]);
  await h.deliverAll(); // worker reports cancelled, ignored
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal((await h.run()).task0, 'failed');
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.equal((await h.run()).status, 'failed');
});

test('late report after timeout is ignored and adds nothing; timeout ends a cancelling run', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0', 2); // report in flight
  await h.taskTimeout(0);
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed', ...noRetry, processed: 1 });

  const g = await createHost();
  await g.start();
  await g.cancel();
  assert.deepEqual(await g.taskTimeout(1), { ok: true });
  assert.equal((await g.run()).status, 'cancelling');
  assert.deepEqual(await g.taskTimeout(0), { ok: true });
  assert.deepEqual(await g.run(), { status: 'failed', task0: 'failed', task1: 'failed', ...noRetry, processed: 0 });
});

test('cancel races with completion', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0', 2); // report in flight
  assert.deepEqual(await h.cancel(), { ok: true });
  const msgs = await h.inFlight();
  assert.equal(msgs.filter((m) => m.action === 'Abort').length, 2);
  for (const m of msgs.filter((m) => m.action === 'Abort')) await h.deliver(m.id);
  assert.equal((await h.run()).status, 'cancelling');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'completed', task1: 'cancelled', ...noRetry, processed: 2 });
  assert.equal((await h.cancel()).ok, false);
});

test('cancel before assign delivered', async () => {
  const h = await createHost();
  await h.start();
  await h.cancel();
  const msgs = await h.inFlight();
  for (const m of msgs.filter((m) => m.action === 'Abort')) await h.deliver(m.id);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.equal((await h.run()).status, 'cancelling');
  await h.workDone('worker0', 1);
  await h.workDone('worker1', 2);
  await h.deliverAll();
  assert.equal((await h.run()).status, 'completed');
  assert.equal((await h.run()).processed, 3);
});

